Ltac rdn_bytes :=
  repeat (apply rdn_cons; [lia | cbn; lia | (match goal with |- rdn _ _ (Z_to_bv 64 ?a) 1 = _ => try (progress (ring_simplify a)) end; match goal with H : L5.u8_at _ _ ?a _ |- rdn _ _ (Z_to_bv 64 ?a) 1 = _ => exact H end) | ]);
  reflexivity.

Section UA.
  Context (fx : FPState).
  Variables (R : bvmap 5 word) (M : word -> option byte) (S p can : Z) (bs t8 : list byte).
  #[local] Notation n := (Z.of_nat (length bs)).
  Hypothesis G1 : getr R (reg 1) = Z_to_bv 64 717576.
  Hypothesis G2 : getr R (reg 2) = Z_to_bv 64 S.
  Hypothesis G10 : getr R (reg 10) = Z_to_bv 64 1412392.
  Hypothesis G11 : getr R (reg 11) = Z_to_bv 64 129768.
  Hypothesis G12 : getr R (reg 12) = Z_to_bv 64 p.
  Hypothesis HS : 140735332552704 + 5440 <= S <= 140737488355328.
  Hypothesis Hal : S mod 16 = 0.
  Hypothesis HW : L5.writable RSEGS M (S - 5440) 5440.
  Hypothesis HD : L5.defined M (S - 5440) 5440.
  Hypothesis HIMG : L5.img_clear M 65536 1400832.
  Hypothesis Hp : S <= p /\ p + n + 1 + 16 <= 2 ^ 47.
  Hypothesis Hn : n <= 62.
  Hypothesis HSTR : cstr M p bs t8.
  Hypothesis HSH : forall x : word, SB + p / 8 - 7 <= bv_unsigned x < Z.min (SB + (p + n) / 8 + 8) (SB + 2 ^ 44) -> M x = Some (Z_to_bv 8 0).
  Hypothesis HSTK : L5KA.zeros_at M (SB + S / 8 - 680) 688.
  Hypothesis HFMT : L5KA.zeros_at M 2147467096 16.
  Hypothesis Hcan : 0 <= can < 2 ^ 64.
  Hypothesis HC : diag_cells M can.
  Hypothesis HSN : sn_cells M.
  Hypothesis HMC : mc_icpt_globs M.

  Definition PRE17 : list byte := ltac2:(Rpl.RP.run_k (rplG ()) 0 "S4;Y3;0;A1;i0;A1;o1;#0;A1;i12;#1;A1;o1;Y6;00;m2;RNLx;RA1;i2;#2;#2;A4;k20;k10;L~RA1;i0;#3;A1;o73;#1;A2;k16;#3;A1;o7;Y16;fae8;N17;2;Ll;R#2;r1;A1;o18;#1;").
  Definition SUF1 : list byte := ltac2:(Rpl.RP.run_k (rplG ()) 0 "S4;Y3;0;A1;i0;A1;o1;#0;A1;i12;#1;A1;o1;Y6;00;m2;RNLx;RA1;i2;#2;#2;A4;k20;k10;L~RA1;i0;#3;A1;o73;#1;A2;k16;#3;A1;o7;Y16;fafb;N1;2;Ll;R#2;r1;A1;o18;#1;").
  Lemma suf1_img : rdn RSEGS (fun _ => None) (Z_to_bv 64 129787) 1 = Some SUF1.  Proof. ltac2:(Rpl.RP.run_k (rplG ()) 0 "S6;Y3;0;A1;i0;A1;o1;#0;A1;i12;#1;A1;i2;#2;A2;o21;#2;k78;A1;o1;Y6;00;cvA2;o19;#3;#4;A3;i11;#3;A4;k20;k10;L~RA1;i0;#5;A1;o73;#1;A2;k16;#5;A1;o7;Y16;fafb;N1;#4;").
