  Lemma PRE17_eq : PRE17 = map (Z_to_bv 8) [99; 108; 105; 58; 32; 99; 97; 110; 110; 111; 116; 32; 111; 112; 101; 110; 32].
  Proof. ltac2:(Rpl.RP.run_k (rplG ()) 0 "S12;Y3;0;A1;o1;#0;A1;i0;#1;A1;o7;Y6;23;Y5;1a;A1;o7;Y5;00;A1;o7;Y6;2e;A1;o7;Y6;2f;A3;o17;i3;#3;A3;o17;i3;A1;o7;Y6;2c;A3;o17;i3;A1;o7;Y6;29;A3;o17;i3;A1;o7;#4;A3;o17;i3;#5;A3;o17;i3;#3;A3;o17;i3;A1;o7;Y6;21;A3;o17;i3;#6;A3;o17;i3;#6;A3;o17;i3;#7;A3;o17;i3;A1;o7;Y6;34;A3;o17;i3;#5;A3;o17;i3;#7;A3;o17;i3;A1;o7;Y6;30;A3;o17;i3;A1;o7;Y6;25;A3;o17;i3;#6;A3;o17;i3;#5;A1;o18;i3;A4;k13;i3;#2;A1;k16;#1;#8;A1;i12;i3;A1;k14;#1;A3;k79;k80;#9;cvA2;o19;#10;#8;A3;i11;#10;A4;k13;#2;i3;#11;k80;A4;k13;#2;i3;#11;#9;").
